CREATE TABLE IF NOT EXISTS zimrx_address_hierarchy (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    country TEXT NOT NULL,
    parent_id INTEGER NULL,
    level INTEGER NOT NULL,
    place_type TEXT NOT NULL,
    name_en TEXT NOT NULL,
    name_loc TEXT NULL,
    postcode TEXT NULL,
    FOREIGN KEY(parent_id) REFERENCES zimrx_address_hierarchy(id)
);

CREATE INDEX IF NOT EXISTS idx_address_country_search ON zimrx_address_hierarchy(country, name_en COLLATE NOCASE, name_loc);
CREATE INDEX IF NOT EXISTS idx_address_parent ON zimrx_address_hierarchy(parent_id);
CREATE INDEX IF NOT EXISTS idx_address_level_type ON zimrx_address_hierarchy(country, level, place_type);

BEGIN TRANSACTION;

DELETE FROM zimrx_address_hierarchy WHERE country = 'BD';

CREATE TEMP TABLE IF NOT EXISTS _tmp_places_seed (
    local_id INTEGER PRIMARY KEY,
    parent_local_id INTEGER NULL,
    country TEXT NOT NULL,
    level INTEGER NOT NULL,
    place_type TEXT NOT NULL,
    name_en TEXT NOT NULL,
    name_loc TEXT NULL,
    postcode TEXT NULL
);
DELETE FROM _tmp_places_seed;


CREATE TEMP TABLE IF NOT EXISTS _base_offset AS SELECT COALESCE(MAX(id), 0) AS offset FROM zimrx_address_hierarchy;
DELETE FROM _base_offset;

SELECT
    t.country,
    CASE WHEN t.parent_local_id IS NULL THEN NULL ELSE t.parent_local_id + b.offset END,
    t.level,
    t.place_type,
    t.name_en,
    t.name_loc,
    t.postcode
FROM _tmp_places_seed t
CROSS JOIN _base_offset b
ORDER BY t.local_id ASC;

DROP TABLE _tmp_places_seed;
DROP TABLE _base_offset;
COMMIT;
